import type { ComponentProps as PlaygroundComponentProps } from "react"
import { Button } from "@/components/ui/button";

import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";

const playgroundProps: Partial<PlaygroundComponentProps<typeof Popover>> = /*__DS_PROPS__*/ {}


