  return (
    <Popover>{playgroundProps.children ?? <>
      <PopoverTrigger asChild>
        <Button variant="outline">Open popover</Button>
      </PopoverTrigger>
      <PopoverContent className="w-64">
        <p className="text-sm">Popover content goes here.</p>
      </PopoverContent>
    </>}</Popover>
  )
}

